def help_articles(language='en'):
    return tuple(Article(key, de_title if language == 'de' else title,
                         de_body if language == 'de' else body)
                 for key, title, body, de_title, de_body in _HELP)


def search_articles(articles, query=''):
    terms = normalized(query).split()
    return tuple(article for article in articles
                 if all(term in normalized(article.title + ' ' + article.body) for term in terms))


def preparation_guide(platform, language='en'):
    """Guidance is platform-specific, never a promise of decryption or signing."""
    common_en = ('1. Close the game; retain an untouched complete original.\n'
                 '2. Make a separate complete export/copy outside live and cloud folders.\n'
                 '3. Confirm the exact profile, region, revision and scope in Compatibility.\n')
    common_de = ('1. Spiel schließen; ein vollständiges unverändertes Original behalten.\n'
                 '2. Vollständige separate Kopie außerhalb aktiver Spiel- und Cloud-Ordner erstellen.\n'
                 '3. Profil, Region, Revision und Umfang unter Kompatibilität prüfen.\n')
    if platform in ('PlayStation 3', 'PlayStation 4', 'PlayStation Vita'):
        en = ('Use the profile-qualified decrypted payload with its original PARAM.SFO or sce_sys/param.sfo when required. Keep the export directory structure intact. Do not synthesize identity/account data. External extraction, encryption, signing and console import remain outside this editor; follow your authorized export tool. A .BIN suffix alone does not establish plaintext compatibility.')
        de = ('Den für das Profil geeigneten entschlüsselten Inhalt mit ursprünglicher PARAM.SFO oder sce_sys/param.sfo verwenden, falls erforderlich. Ordnerstruktur erhalten. Keine Identitäts- oder Kontodaten erzeugen. Extraktion, Verschlüsselung, Signierung und Konsolenimport erfolgen außerhalb dieses Editors über ein autorisiertes Exportwerkzeug. Die Endung .BIN beweist keine Klartext-Kompatibilität.')
    elif platform == 'PlayStation 2':
        en = 'Use the exact supported PSU memory-card export and region. Keep container entries and companion metadata intact; a raw memory-card image or renamed PC save is not equivalent. Import the exported edited copy with your memory-card tool after validation.'
        de = 'Den exakt unterstützten PSU-Speicherkartenexport und die richtige Region verwenden. Containereinträge und Metadaten erhalten; ein Speicherkartenabbild oder umbenannter PC-Spielstand ist nicht gleichwertig. Die bearbeitete Kopie nach Prüfung mit dem Speicherkartenwerkzeug importieren.'
    elif platform.startswith('Nintendo') or platform in ('Wii U', 'NES', 'SNES'):
        en = 'Use the exact supported extracted gameplay payload or raw battery SRAM for this profile, not an encrypted archive, emulator wrapper or full system image. Keep title/export metadata and other slots together. Reimport a copy using your authorized platform tool; the editor does not modify ownership or signing.'
        de = 'Die exakt unterstützten extrahierten Spieldaten oder das rohe Batterie-SRAM verwenden, kein verschlüsseltes Archiv, Emulator-Wrapper oder Systemabbild. Titelmetadaten und andere Slots zusammenhalten. Eine Kopie mit dem autorisierten Plattformwerkzeug importieren; Besitz und Signierung werden nicht verändert.'
    elif 'Xbox' in platform:
        en = 'Use the exact supported extracted native payload. Xbox 360/Xenia story profiles differ from Original Xbox profiles. Original Xbox profiles may require original console EEPROM context; retain it privately and follow the exact profile instructions. Container extraction and signing stay external. Never share EEPROM or account material in reports.'
        de = 'Die exakt unterstützten extrahierten nativen Daten verwenden. Xbox-360/Xenia-Storyprofile unterscheiden sich vom Original Xbox. Original-Xbox-Profile können den ursprünglichen EEPROM-Kontext benötigen; privat behalten und die genauen Profilhinweise beachten. Extraktion und Signierung bleiben extern. EEPROM- und Kontodaten nie in Berichten teilen.'
    else:
        en = 'Pause Steam/cloud synchronization before copying the complete save folder. Select the exact native slot/system file required by the profile; keep original identity companions together when required. DOS and Macintosh profiles require their documented raw file/data fork, not an emulator container. Export to a new destination; restore/import only after closing the game and retaining a recovery copy.'
        de = 'Steam-/Cloud-Synchronisierung vor dem Kopieren des vollständigen Speicherordners pausieren. Die für das Profil geforderte native Slot-/Systemdatei wählen und nötige Identitäts-Begleitdateien zusammenhalten. DOS- und Macintosh-Profile benötigen die dokumentierte Rohdatei bzw. den Daten-Fork statt eines Emulatorcontainers. In ein neues Ziel exportieren; nur bei geschlossenem Spiel und mit Wiederherstellungskopie importieren.'
    end_en = '\n5. Open the copy, make one supported change, Review Changes, then Save As to a new destination.\n6. Load in the same game build, check the change, re-save and load again. Record each result in Validation.'
    end_de = '\n5. Kopie öffnen, eine unterstützte Änderung vornehmen, Änderungen prüfen und Speichern unter in ein neues Ziel.\n6. In der gleichen Spielversion laden, Änderung prüfen, erneut speichern und laden. Jedes Ergebnis unter Validierung erfassen.'
    return (common_de + '4. ' + de + end_de if language == 'de' else common_en + '4. ' + en + end_en)
